/* =====================================================================
   HEREDEROS DEL REY · DATOS DE PRUEBA DE FARMACIA
   Base de datos: HDR3 (SQL Server)

   Simula 45 días de operación de una farmacia (2026-09-19 al 2026-11-02)
   en Sucursal Central (Id 1) y Sucursal Norte (Id 2):
     - 47 medicamentos e insumos (10 categorías, 13 laboratorios/marcas)
     - compras a droguerías que crean lotes con vencimiento y suben el stock
     - ventas al contado y a crédito (FEFO por lote) con sus pagos y abonos;
       los créditos son de clientes institucionales (clínicas, consultorios)
     - una caja por día y sucursal, cerrada con su monto final
     - gastos de farmacia (alquiler, regente, licencia SEDES, cadena de frío...)

   Todo cuadra: stock = compras - ventas, y el stock de productos con lote
   es igual a la suma de sus lotes. Quedan lotes vencidos y por vencer
   para la vista de Vencimientos, y créditos pendientes y vencidos.

   Todos los registros nuevos usan Id >= 90001.
   Para quitarlos, ejecuta: datos-prueba-hdr-deshacer.sql
   ===================================================================== */

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF EXISTS (SELECT 1 FROM dbo.Productos WHERE Id = 90001)
BEGIN
    RAISERROR('Los datos de prueba ya fueron cargados (existe el producto 90001). Ejecuta primero el script de deshacer.', 16, 1);
    RETURN;
END;

BEGIN TRANSACTION;

